public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    if (!file.exists()) {
        // Nothing to schedule if the file does not exist
        return;
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children == null) {
            throw new IOException("Unable to read directory: " + file.getAbsolutePath());
        }
        // Schedule deletion for all children before the directory itself
        for (File child : children) {
            forceDeleteOnExit(child);
        }
    }
    file.deleteOnExit();
}

