public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type raw = pType.getRawType();
    if (!(raw instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) raw;

    // The target type must be the same class or a subclass/a subtype of the raw type
    if (targetType != rawClass && !rawClass.isAssignableFrom(targetType)) {
        return null;
    }

    // Retrieve the actual type arguments from the parameterized type
    Type[] actualArgs = pType.getActualTypeArguments();
    if (actualArgs == null || actualArgs.length == 0) {
        return null;
    }

    Class<?>[] resolved = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type arg = actualArgs[i];
        if (arg instanceof Class<?>) {
            resolved[i] = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type rt = ((ParameterizedType) arg).getRawType();
            if (rt instanceof Class<?>) {
                resolved[i] = (Class<?>) rt;
            } else {
                return null;
            }
        } else {
            // Cannot resolve TypeVariable, Wildcard, or generic array type
            return null;
        }
    }
    return resolved;
}

