public long readRawVarint64() throws IOException {
    long result = 0L;
    int shift = 0;
    for (int i = 0; i < 10; i++) {
        int b = input.read();
        if (b == -1) {
            throw new EOFException("Stream ended prematurely while reading varint");
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Varint too long");
}

