        throw new IndexOutOfBoundsException(
            "offset=" + off + ", len=" + len + ", b.length=" + b.length);
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        buf = java.util.Arrays.copyOf(buf, Math.max(buf.length << 1, newCount));
    }
