public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("Input stream cannot be null");
    }
    // Read the entire stream into a temporary buffer
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] tmp = new byte[8192];
    int bytesRead;
    while ((bytesRead = in.read(tmp)) != -1) {
        baos.write(tmp, 0, bytesRead);
    }
    byte[] newData = baos.toByteArray();

    // Replace existing buffer content (clear and fill)
    if (buffer == null || buffer.length < newData.length) {
        buffer = new byte[newData.length];
    }
    System.arraycopy(newData, 0, buffer, 0, newData.length);

    // Reset the read pointer to the start of the byte array
    ptr = 0;
}

