public String toString(JSONWriter.Feature... features){
    try{
        StringWriter sw = new StringWriter();
        JSONWriter jw = new JSONWriter(sw);
        if(features != null){
            for(JSONWriter.Feature f : features){
                if(f != null){
                    jw.setFeature(f);
                }
            }
        }
        jw.object();
        Class<?> cls = getClass();
        while(cls != null){
            Field[] fields = cls.getDeclaredFields();
            for(Field field : fields){
                int mods = field.getModifiers();
                if(java.lang.reflect.Modifier.isStatic(mods) || java.lang.reflect.Modifier.isTransient(mods)){
                    continue;
                }
                field.setAccessible(true);
                Object value = field.get(this);
                jw.name(field.getName()).value(value);
            }
            cls = cls.getSuperclass();
        }
        jw.endObject();
        return sw.toString();
    }catch(Exception e){
        throw new RuntimeException("Serialization to JSON failed", e);
    }
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0);
        } else {
            throw new Exception("String length must be exactly 1 to convert to Character");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
            return (char) intVal;
        } else {
            throw new Exception("Numeric value out of char range: " + intVal);
        }
    }
    throw new Exception("Unsupported conversion from " + value.getClass().getName() + " to Character");
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Ensure candidate is odd
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Increase by 2 to stay odd
        // Avoid overflow: if candidate is close to Integer.MAX_VALUE, return Integer.MAX_VALUE
        if (candidate >= Integer.MAX_VALUE - 2) {
            return Integer.MAX_VALUE;
        }
        candidate += 2;
    }

    /* Helper method to test primality */
    static boolean isPrime(int n){
        if (n <= 3) {
            return n > 1;
        }
        if ((n & 1) == 0) {
            return false;
        }
        int sqrt = (int)Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

