private static int digitValue(final char c) {
    // Check for ASCII digit characters '0'-'9'
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // Check for ASCII lowercase letters 'a'-'z'
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    // Check for ASCII uppercase letters 'A'-'Z'
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    // For any non-ASCII or non-digit character return -1 to indicate invalid
    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if (jsonObject == null) {
        return content;
    }
    try {
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement value = entry.getValue();
            if (value == null || value.isJsonNull()) {
                content.put(key, null);
            } else if (value.isJsonPrimitive()) {
                JsonPrimitive prim = value.getAsJsonPrimitive();
                if (prim.isBoolean()) {
                    content.put(key, prim.getAsBoolean());
                } else if (prim.isNumber()) {
                    content.put(key, prim.getAsNumber());
                } else if (prim.isString()) {
                    content.put(key, prim.getAsString());
                } else {
                    content.put(key, prim.getAsString());
                }
            } else if (value.isJsonObject()) {
                content.put(key, buildContent(value.getAsJsonObject()));
            } else if (value.isJsonArray()) {
                // Convert JsonArray into List<Object>
                List<Object> list = new ArrayList<>();
                for (JsonElement elem : value.getAsJsonArray()) {
                    if (elem.isJsonPrimitive()) {
                        JsonPrimitive p = elem.getAsJsonPrimitive();
                        if (p.isBoolean()) {
                            list.add(p.getAsBoolean());
                        } else if (p.isNumber()) {
                            list.add(p.getAsNumber());
                        } else if (p.isString()) {
                            list.add(p.getAsString());
                        } else {
                            list.add(p.getAsString());
                        }
                    } else if (elem.isJsonObject()) {
                        list.add(buildContent(elem.getAsJsonObject()));
                    } else if (elem.isJsonArray()) {
                        // recursion depth minimal; convert sub‑array to list of strings
                        list.add(elem.toString());
                    } else {
                        list.add(null);
                    }
                }
                content.put(key, list);
            } else {
                content.put(key, value.toString());
            }
        }
    } catch (Exception e) {
        // Silently handle any unexpected issues; the caller can decide what to do
    }
    return content;
}

