public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        if (i == len - 1) {
            throw new Exception("Trailing backslash in string");
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                if (i + 5 >= len) {
                    throw new Exception("Incomplete Unicode escape sequence");
                }
                String hex = str.substring(i + 2, i + 6);
                int codePoint;
                try {
                    codePoint = Integer.parseInt(hex, 16);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid Unicode escape sequence: \\u" + hex);
                }
                sb.append((char) codePoint);
                i += 5;
                break;
            default:
                if (next >= '0' && next <= '7') {
                    int oct = next - '0';
                    int digits = 1;
                    if (i + 2 < len) {
                        char c2 = str.charAt(i + 2);
                        if (c2 >= '0' && c2 <= '7') {
                            oct = oct * 8 + (c2 - '0');
                            digits++;
                            if (i + 3 < len) {
                                char c3 = str.charAt(i + 3);
                                if (c3 >= '0' && c3 <= '7') {
                                    oct = oct * 8 + (c3 - '0');
                                    digits++;
                                }
                            }
                        }
                    }
                    sb.append((char) oct);
                    i += digits;
                } else {
                    sb.append(next);
                    i++;
                }
                break;
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset){  
    if (charset == null) {  
        return null;  
    }  
    String trimmed = charset.trim();  
    if (trimmed.isEmpty()) {  
        return trimmed;  
    }  
    String lc = trimmed.toLowerCase(java.util.Locale.ENGLISH);  
    switch (lc) {  
        case "utf-8":  
        case "utf8":  
            return "UTF-8";  
        case "utf-16":  
        case "utf16":  
            return "UTF-16";  
        case "iso-8859-1":  
        case "iso8859-1":  
            return "ISO-8859-1";  
        case "us-ascii":  
        case "usascii":  
            return "US-ASCII";  
        default:  
            // Try to get the canonical name if Java supports it  
            try {  
                return java.nio.charset.Charset.forName(trimmed).name();  
            } catch (Exception e) {  
                // If not supported, return the trimmed input as is  
                return trimmed;  
            }  
    }  
}

