public short readShort(final int offset){
    // Validate offset bounds against the internal byte array 'data'
    if (offset < 0 || offset + 1 >= this.data.length) {
        throw new ArrayIndexOutOfBoundsException(
            "offset out of bounds: " + offset + ", data length: " + this.data.length);
    }
    // Combine two bytes into a signed 16‑bit short
    return (short) ((this.data[offset] << 8) | (this.data[offset + 1] & 0xFF));
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("newArrayComponentType must not be null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("array must be an array");
    }
    int oldLen = java.lang.reflect.Array.getLength(array);
    Object newArray = java.lang.reflect.Array.newInstance(arrayClass.getComponentType(), oldLen + 1);
    System.arraycopy(array, 0, newArray, 0, oldLen);
    return newArray;
}

private int computeBinaryLog(int n){ 
    if (n <= 0) { 
