private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes cannot be null");
    }
    Node current = start;
    // Use a do-while loop to ensure we evaluate the start node first
    do {
        // If the current node satisfies the predicate, return a circulator starting there
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        // If we have reached the stop node, return a circulator to the stop node
        if (current.equals(stop)) {
            return new OuterFaceCirculator(stop);
        }
        // Determine the next node in the specified traversal direction
        // The actual method name may vary; adjust accordingly if different in the real codebase
        try {
            current = current.getAdjacentNode(dir);
        } catch (Exception e) {
            // If the node does not provide a suitable method, fail gracefully
            return new OuterFaceCirculator(stop);
        }
        if (current == null) {
            // No more nodes to visit; terminate here
            break;
        }
    } while (!current.equals(start));
    // If we exit the loop without satisfying the predicate, fallback to the stop node circulator
    return new OuterFaceCirculator(stop);
}

