protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty() || graph == null){
        return null;
    }
    // Copy remaining edges
    Set<E> remaining = new HashSet<>(tour);
    // Pick an arbitrary start edge
    E startEdge = remaining.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    // Find the other vertex of the start edge
    V otherVertex = graph.getEdgeTarget(startEdge).equals(startVertex)
            ? graph.getEdgeSource(startEdge)
            : graph.getEdgeTarget(startEdge);
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    vertexList.add(startVertex);
    edgeList.add(startEdge);
    remaining.remove(startEdge);
    V currentVertex = otherVertex;
    vertexList.add(currentVertex);
    // Build path by following unused edges
    while (!remaining.isEmpty()){
        boolean found = false;
        for (E e : graph.edgesOf(currentVertex)){
            if (remaining.contains(e)){
                edgeList.add(e);
                remaining.remove(e);
                V next = graph.getEdgeSource(e).equals(currentVertex)
                        ? graph.getEdgeTarget(e)
                        : graph.getEdgeSource(e);
                vertexList.add(next);
                currentVertex = next;
                found = true;
                break;
            }
        }
        if (!found){
            throw new IllegalArgumentException("The provided set of edges does not form a continuous path");
        }
    }
    // Construct and return the graph path
    return org.jgrapht.graph.GraphPaths.getPath(graph, vertexList, edgeList);
}

