        if (pos >= len) {
            return "";
        }
        int start = pos;
        while (pos < len) {
            char c = buffer.charAt(pos);
            boolean isTerm = false;
            for (int i = 0; i < terminators.length; i++) {
                if (c == terminators[i]) {
                    isTerm = true;
                    break;
                }
            }
            if (isTerm) {
                break;
            }
            pos++;
        }
        String token = buffer.substring(start, pos);
        if (pos < len) {
            pos++;  // consume the terminating character
        }
        return token;
    } catch (Exception e) {
        throw new RuntimeException("Error during parseToken()", e);
    }
}

