private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    // initialize with zeros
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    long runningSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        suffix.set(i, (int) runningSum);
    }
    long totalSum = bounds.stream().mapToLong(Integer::longValue).sum();
    return new Pair<>(suffix, totalSum);
}

void function ( V[] arr , int from , int to ) {
