        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    try {
        ListNodeImpl<E> node;
        // Move each node from the source list to this list until the source is empty
        while ((node = list.getHead()) != null) {
            list.removeListNode(node);   // atomically remove from source
            this.addListNode(node);      // atomically add to destination
        }
    } catch (Exception e) {
        // In the event of any runtime failure, wrap and rethrow so callers are aware
        throw new IllegalStateException("Failed to move all list nodes", e);
    }
}

