public static String[] split(String toSplit, String delimiter) {
    // Null checks: return null if either argument is null
    if (toSplit == null || delimiter == null) {
        return null;
    }
    // Find the first occurrence of the delimiter
    int delimIndex = toSplit.indexOf(delimiter);
    if (delimIndex == -1) {
        // Delimiter not found
        return null;
    }
    // Extract parts before and after the delimiter
    String before = toSplit.substring(0, delimIndex);
    String after = toSplit.substring(delimIndex + delimiter.length());
    return new String[] { before, after };
}

