public static Type resolveBound(TypeVariable<?> typeVariable){
    try{
        if(typeVariable == null){
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if(bounds == null || bounds.length == 0){
            return Unknown.class;
        }
        Type bound = bounds[0];
        if(bound instanceof Class<?>){
            return bound;
        }
        if(bound instanceof java.lang.reflect.ParameterizedType){
            Type raw = ((java.lang.reflect.ParameterizedType)bound).getRawType();
            if(raw instanceof Class<?>){
                return raw;
            }
        }
    }catch(Exception e){
        // ignore any reflection related errors
    }
    return Unknown.class;
}

