private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null){
        return result;
    }
    // Build a sorted set of comparable keys
    TreeSet<Comparable> sorted = new TreeSet<>();
    for (K key : keys){
        if (key instanceof Comparable){
            //noinspection unchecked
            sorted.add((Comparable) key);
        }
    }
    for (K key : keys){
        if (!(key instanceof Comparable)){
            result.add(Integer.MIN_VALUE);
            continue;
        }
        Comparable thisKey = (Comparable) key;
        Comparable floor = sorted.floor(thisKey);
        if (floor == null){
            result.add(Integer.MIN_VALUE);
        } else if (floor instanceof Number){
            result.add(((Number) floor).intValue());
        } else if (floor instanceof String){
            try{
                result.add(Integer.parseInt((String) floor));
            }catch (NumberFormatException e){
                result.add(Integer.MIN_VALUE);
            }
        } else {
            result.add(Integer.MIN_VALUE);
        }
    }
    return result;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null){
        return new ArrayList<Integer>();
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys){
        int upper = 0;
        try {
            if (key instanceof Number){
                upper = ((Number)key).intValue() + 1;
            } else {
                upper = Integer.parseInt(key.toString()) + 1;
            }
        } catch (Exception e){
            upper = 0; // fallback for non-numeric keys
        }
        bounds.add(upper);
    }
    return bounds;
}

