public static String applyRelativePath(String path,String relativePath){
    if (path == null || path.isEmpty()) return relativePath;
    if (relativePath == null || relativePath.isEmpty()) return path;
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    String[] baseParts = path.split("/");
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.pollLast();
        } else {
            stack.addLast(part);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.pollLast();
        } else {
            stack.addLast(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    boolean leadingSlash = path.startsWith("/");
    if (leadingSlash) sb.append("/");
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) sb.append("/");
    }
    return sb.toString();
}

static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    for (Object element : array) {
        if (element != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        // All elements are non‑null; cast is safe if the array actually holds Strings
        return (String[]) array;
    }
    String[] result = new String[nonNullCount];
    int pos = 0;
    for (Object element : array) {
        if (element != null) {
            result[pos++] = (String) element;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSlash = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    return lastDot > lastSlash ? lastDot : -1;
}

