public static String toString(final char ch) {
    // If the character is within the ASCII 7‑bit range, we can safely reuse a cached
    // single‑character string.  The cache is stored in a static array in the same
    // class.  If the cache is not initialized yet, we lazily create a string and
    // store it for future reuse.
    if (ch < 128) {
        // The cache is expected to be a static array of length 128.  We use
        // System.arraycopy to initialise it on first access without synchronization
        // overhead, as the array is immutable after initialisation.
        if (CharUtils.cached[ch] == null) {
            CharUtils.cached[ch] = new String(new char[] { ch });
        }
        return CharUtils.cached[ch];
    }

    // For non‑ASCII characters, just construct a new string.
    return new String(new char[] { ch });
}

private void checkIfPackedField() throws IOException {
    // Check if the current field is a length‑delimited field that has been marked as packed.
    // If so, read the packed length and set the internal state so that packed values can be read.
    if (wireType == WIRETYPE_LENGTH_DELIMITED && isPacked) {
        int packedLength = readVarint32(); // length prefix of the packed field
        if (packedLength < 0) {
            throw new IOException("Invalid packed field length: " + packedLength);
        }
        packedFieldEndPosition = getCurrentPosition() + packedLength;
        isReadingPacked = true;
    } else {
        isReadingPacked = false;
    }
}

public int readTag() throws IOException {
    int tag = 0;
    for (int shift = 0; shift < 32; shift += 7) {
        int b = input.read();                         // read one byte from the underlying source
        if (b == -1) {                               // EOF reached before we could read a complete tag
            return 0;
        }
        tag |= (b & 0x7F) << shift;                  // add the 7 bits of data to the tag
        if ((b & 0x80) == 0) {                       // high bit 0 -> this is the last byte of the varint
            return tag;                              // return the constructed tag
        }
    }
    // If we reach here, the varint was too long (more than 5 bytes) which is malformed
    throw new IOException("Malformed varint tag");
}

