public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("File must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a regular file: " + file);
    }
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Assume each line starts with a long timestamp followed by a comma.
            String[] parts = line.split(",", 2);
            if (parts.length == 0) {
                continue;
            }
            try {
                long ts = Long.parseLong(parts[0].trim());
                // Create a snapshot instance via no‑arg constructor if available.
                ThreadSnapshot snap = null;
                try {
                    snap = ThreadSnapshot.class.getDeclaredConstructor().newInstance();
                } catch (Exception ignored) {
                    // If no no‑arg constructor, skip this line.
                    continue;
                }
                // Try to set a field named "timestamp" if present.
                try {
                    java.lang.reflect.Field f = ThreadSnapshot.class.getDeclaredField("timestamp");
                    f.setAccessible(true);
                    f.set(snap, ts);
                } catch (Exception ignored) {
                    // ignore if field not present
                }
                snapshots.add(snap);
            } catch (NumberFormatException e) {
                // Not a valid long, skip this line.
            }
        }
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return snapshots;
    }
    List<ThreadSnapshot> filtered = new ArrayList<>();
    for (ThreadSnapshot snap : snapshots) {
        boolean withinAny = false;
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            try {
                // Attempt to get timestamp from snapshot.
                long snapTime = (Long) ThreadSnapshot.class.getMethod("getTimestamp").invoke(snap);
                long start = (Long) range.getClass().getMethod("getStart").invoke(range);
                long end   = (Long) range.getClass().getMethod("getEnd").invoke(range);
                if (snapTime >= start && snapTime <= end) {
                    withinAny = true;
                    break;
                }
            } catch (Exception ignored) {
                // If any method is missing, skip this snapshot or range.
            }
        }
        if (withinAny) {
            filtered.add(snap);
        }
    }
    return filtered;
}
